"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[36028],{36028:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<TvCard\\n  cover=\\"/assets/snippets/screen/wonderfulsseason12026.jpg\\"\\n  title=\\"원더풀스 시즌 1 (2026)\\"\\n  release_date=\\"2026-05-15\\"\\n  episode_count=8\\n  genres=[\\"코미디\\",\\"미스터리\\"]\\n  rating=2\\n  tags=\\"tv\\"\\n/>\\n</center>\\n\\n## Review\\n코미디 장르라는 걸 알고 시작했다.  \\n그래서 어느 정도 가볍게 보려 마음먹었는데, 문제는 코미디도, 긴장감도 어중간했다는 것이다.  \\n\\n스토리는 처음부터 끝이 보인다.  \\n<mark>히어로</mark>물 특유의 클리셰를 그대로 가져왔고, 놀랍거나 뒤집히는 순간이 없다.  \\n이렇게 예상 가능한 전개라면 차라리 빠른 호흡의 액션으로 밀어붙이거나, 코미디에 완전히 집중하거나 선택 했어야 했다.  \\n하지만 이 드라마는 그 중간 어딘가에서 방향을 못 잡고 내내 흔들렸다.  \\n```adcard\\n```\\n코미디 장면들은 기대보다 힘이 없었다.  \\n웃기려는 의도는 보이지만 실제로 웃음이 터지는 순간은 드물었다.  \\n진지한 감정 신으로 넘어가면 그나마 있던 에너지도 빠지는 느낌이었다.  \\n\\n전개가 너무 늘어진다.  \\n8부작임에도 중반부가 지나면서 지루함이 쌓이기 시작했고, 결말에 다가갈수록 완결보다는 시즌 2를 염두에 둔 열린 마무리라는 게 눈에 보였다.  \\n시즌 2로 이어질 수도 있다는 걸 알면서도, 이번 시즌이 충분하지 않았는데 다음을 기대하기가 쉽지 않다."}')}}]);